import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testFindMiddle() {
        Assert.assertEquals(1, linearSearch(listOf(45, 72, 38, 91), 72))
    }

    @Test
    fun testNotFound() {
        Assert.assertEquals(-1, linearSearch(listOf(45, 72, 38, 91), 99))
    }

    @Test
    fun testFindFirst() {
        Assert.assertEquals(0, linearSearch(listOf(45, 72, 38, 91), 45))
    }

    @Test
    fun testFindLast() {
        Assert.assertEquals(3, linearSearch(listOf(45, 72, 38, 91), 91))
    }
